/* =============================================================================
   CADEIRA v3 — Brasões (Mauá, São Paulo, República) e cerimônia de diplomação
   - Brasão ao lado do nome no cabeçalho quando o jogador tem cargo.
   - "Quem governa" no topo de Poder: os três chefes do Executivo com brasão.
   - Brasão no gabinete da pasta.
   - Cerimônia: ao ser eleito(a), diploma da Justiça Eleitoral com brasão,
     assinatura e carimbo; ao assumir pasta, termo de posse.
   Imagens enviadas pelo dono do jogo, sem fundo, até 240 px (WebP).
   ============================================================================= */
(function () {
  "use strict";
  if (window.V3BRASOES) return;
  var BR = (window.V3BRASOES = {"maua": "data:image/webp;base64,", "sp": "data:image/webp;base64,", "br": "data:image/webp;base64,"});
  function esc_(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); }
  function ok(f, d) { try { var v = f(); return v === undefined ? d : v; } catch (e) { return d; } }
  var NIVEL = { VER: "maua", PREF: "maua", SECM: "maua", DEPE: "sp", GOV: "sp", SECE: "sp", DEPF: "br", SEN: "br", PRES: "br", MIN: "br" };
  var ALT = { maua: "Brasão de Mauá", sp: "Brasão do Estado de São Paulo", br: "Brasão da República" };
  var ELETIVOS = { VER: 1, PREF: 1, DEPE: 1, GOV: 1, DEPF: 1, SEN: 1, PRES: 1 };
  var PASTA = { SECM: 1, SECE: 1, MIN: 1 };
  function img(k, cls) { return '<img class="' + (cls || "v3-brasao") + '" src="' + BR[k] + '" alt="' + ALT[k] + '">'; }
  function cid() { return ok(function () { return cargoAtualId(); }, "CIDADAO"); }
  window.V3BRASAO = function (nivelOuCargo, cls) { var k = BR[nivelOuCargo] ? nivelOuCargo : NIVEL[nivelOuCargo] || ({ M: "maua", E: "sp", F: "br" })[nivelOuCargo]; return k ? img(k, cls) : ""; };

  /* ---------------------------------------------------------------- cabeçalho */
  function cabecalho() {
    var k = NIVEL[cid()]; if (!k) return;
    var who = document.querySelector("#app > header.lcd .who"); if (!who || who.querySelector(".v3-brasao-h")) return;
    who.insertAdjacentHTML("afterbegin", img(k, "v3-brasao-h"));
  }

  /* ---------------------------------------------------------------- quem governa */
  function chefe(cargo) {
    try { if (J().cargo_atual === cargo) return { nome: J().nome + " (você)", partido: J().partido_atual, eu: true }; } catch (e) {}
    var n = ok(function () { return bancoDeNPCs.find(function (x) { return x.vivo && x.cargo === cargo; }); }, null);
    return n ? { nome: n.nome, partido: n.partidoBase || n.partido, rel: n.relacao_com_jogador } : null;
  }
  function quemGoverna() {
    var linhas = [["br", "Presidente da República", "Brasil", "Presidente"], ["sp", "Governador de SP", "São Paulo", "Governador(a)"], ["maua", "Prefeito de Mauá", "Mauá", "Prefeito(a)"]];
    return '<section class="v3-qg"><div class="v3-qg-h"><span class="pf-kicker">PODER EXECUTIVO</span><h2>Quem governa</h2></div><div class="v3-qg-g">' + linhas.map(function (l) {
      var c = chefe(l[1]);
      var rel = c && typeof c.rel === "number" ? (c.rel >= 30 ? "aliado(a) seu" : c.rel <= -20 ? "adversário(a) seu" : "relação neutra") : "";
      return '<div class="v3-qg-i' + (c && c.eu ? " eu" : "") + '">' + img(l[0], "v3-qg-b") + "<div><small>" + esc_(l[2]) + "</small><b>" + esc_(c ? c.nome : "Vago") + "</b><span>" + esc_(l[3]) + (c && c.partido ? " · " + esc_(c.partido) : "") + (rel ? " · " + rel : "") + "</span></div></div>";
    }).join("") + "</div></section>";
  }
  function poderTopo() {
    if (ok(function () { return S.tab; }, "") !== "poder") return;
    var main = document.getElementById("main"); if (!main || main.querySelector(".v3-qg")) return;
    main.insertAdjacentHTML("afterbegin", quemGoverna());
  }
  function pastaCab() {
    var cab = document.querySelector(".p3-cab"); if (!cab || cab.querySelector(".v3-brasao-p")) return;
    var p = ok(function () { return J().pasta; }, null); if (!p) return;
    cab.insertAdjacentHTML("afterbegin", img(({ M: "maua", E: "sp", F: "br" })[p.nivel] || "br", "v3-brasao-p"));
  }

  /* ---------------------------------------------------------------- cerimônia */
  var EMISSOR = { maua: "Justiça Eleitoral · Zona Eleitoral de Mauá", sp: "Tribunal Regional Eleitoral de São Paulo", br: "Tribunal Superior Eleitoral" };
  var EMISSOR_POSSE = { maua: "Prefeitura do Município de Mauá", sp: "Governo do Estado de São Paulo", br: "Presidência da República" };
  var fila = null;
  function estado() { var j = ok(function () { return J(); }, null); if (!j) return null; j.v3posse = j.v3posse || { cargo: null }; return j.v3posse; }
  function verificar() {
    var st = estado(); if (!st) return;
    var j = J(), c = cid(), chave = j.cargo_atual + "|" + (j.pasta ? j.pasta.id : "") + "|" + (j.mandato_fim || "");
    if (st.cargo === null) { st.cargo = chave; return; } // primeira vez: só memoriza
    if (st.cargo === chave) return;
    var mesmoCargo = st.cargo.split("|")[0] === j.cargo_atual && !PASTA[c];
    st.cargo = chave;
    if ((ELETIVOS[c] || PASTA[c]) && !(mesmoCargo && !ELETIVOS[c])) fila = { tipo: PASTA[c] ? "posse" : "diploma", c: c, cargo: j.cargo_atual, pasta: j.pasta ? j.pasta.nome : null, ano: ok(function () { return dt().ano; }, 2026), fim: j.mandato_fim, partido: j.partido_atual, nome: j.nome, nivel: NIVEL[c] || "br", sexo: j.sexo, reeleito: mesmoCargo };
  }
  function bloqueado() { return !!document.querySelector("#apurMapa, .evping, .dip-modal, #v3m-ping.grande, #app .modal"); }
  function mostrar() {
    if (!fila || bloqueado() || document.getElementById("v3-cerimonia")) return;
    var f = fila; fila = null;
    var a = f.sexo === "F" ? "a" : "o";
    var corpo = f.tipo === "diploma"
      ? "<p>A Justiça Eleitoral, nos termos do Código Eleitoral, confere a</p><h2>" + esc_(f.nome) + "</h2><p>" + (f.reeleito ? "reeleit" : "eleit") + a + " para o cargo de <b>" + esc_(f.cargo) + "</b> pelo <b>" + esc_(f.partido) + "</b> nas Eleições de " + f.ano + (f.fim ? ", com mandato até " + f.fim : "") + ", o presente</p><h3>DIPLOMA</h3>"
      : "<p>Neste ano de " + f.ano + ", compareceu perante a autoridade competente</p><h2>" + esc_(f.nome) + "</h2><p>que, nomead" + a + " para <b>" + esc_(f.pasta || f.cargo) + "</b>, assume o compromisso de cumprir a Constituição e as leis, lavrando-se o presente</p><h3>TERMO DE POSSE</h3>";
    var conf = "";
    for (var i = 0; i < 36; i++) conf += '<i style="left:' + (i * 2.8 + Math.random() * 2).toFixed(1) + "%;animation-delay:" + (1.6 + Math.random() * 1.4).toFixed(2) + "s;animation-duration:" + (2.4 + Math.random() * 2).toFixed(2) + 's"></i>';
    var html = '<div id="v3-cerimonia" role="dialog" aria-label="Cerimônia de ' + (f.tipo === "diploma" ? "diplomação" : "posse") + '"><div class="v3c-luz"></div><div class="v3c-pap">' +
      '<div class="v3c-bra">' + img(f.nivel, "v3c-img") + "</div>" +
      '<div class="v3c-emi">' + esc_(f.tipo === "diploma" ? EMISSOR[f.nivel] : EMISSOR_POSSE[f.nivel]) + "</div>" +
      '<div class="v3c-txt">' + corpo + "</div>" +
      '<div class="v3c-ass"><svg viewBox="0 0 220 50" aria-hidden="true"><path d="M8 34 C 26 10, 40 44, 58 26 S 86 8, 98 30 S 122 46, 138 22 S 168 14, 178 30 C 186 40, 198 26, 212 24"/></svg><span>' + esc_(f.tipo === "diploma" ? "Juiz(a) Eleitoral" : "Autoridade empossante") + "</span></div>" +
      '<div class="v3c-selo">' + (f.tipo === "diploma" ? "DIPLOMAD" : "EMPOSSAD") + a.toUpperCase() + "</div>" +
      '<button type="button" class="b confirma v3c-ok">' + (f.tipo === "diploma" ? "Tomar posse" : "Assumir o cargo") + "</button></div>" +
      '<div class="v3c-conf">' + conf + "</div></div>";
    document.body.insertAdjacentHTML("beforeend", html);
    try { if (typeof beep === "function") beep(); } catch (e) {}
    var el = document.getElementById("v3-cerimonia");
    el.querySelector(".v3c-ok").addEventListener("click", function () { el.classList.add("sai"); setTimeout(function () { el.remove(); }, 400); });
  }
  window.V3CERIMONIA = function (dados) { fila = dados; mostrar(); };

  /* ---------------------------------------------------------------- instalação */
  function aposRender() {
    try { if (!ok(function () { return !!gameState; }, false)) return; verificar(); cabecalho(); poderTopo(); pastaCab(); mostrar(); } catch (e) { console.warn("brasoes", e); }
  }
  function instalar() {
    if (typeof window.render === "function" && !window.render.__v3bras) {
      var o = window.render;
      var n = function () { var r = o.apply(this, arguments); aposRender(); return r; };
      for (var k in o) { try { n[k] = o[k]; } catch (e) {} }
      n.__v3bras = true; window.render = n; try { render = n; } catch (e) {}
    }
  }
  setInterval(function () { try { if (fila) mostrar(); } catch (e) {} }, 1500);
  instalar();
  document.addEventListener("DOMContentLoaded", function () { setTimeout(instalar, 0); });
  window.addEventListener("load", function () { setTimeout(instalar, 0); });
})();
